var e=e=>e>0?1+e/100:1+100/Math.abs(e);function t(t){let n=t.bankroll*Math.max(0,t.targetLossPct),r=Math.max(0,t.currentExposure-n);if(r<=0)return{stake:0,reason:`Exposure already within target`};let i=e(t.hedgeOdds)-1,a=i>0?r/i:0,o=Math.max(.25,Math.min(1,t.hedgeWinProbability/.5)),s=Math.min(t.bankroll*.05,a*o);return{stake:s,reason:s>0?`Sized to reduce downside without over-hedging`:`No efficient hedge`}}async function n(e){let n=await e.json();return Response.json(t(n))}export{n as POST};